export function add(a, b) {
  return a + b;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { add } from "./add.js";

test("suma dos números positivos", () => {
  assert.equal(add(2, 3), 5);
});

test("suma negativos", () => {
  assert.equal(add(-2, -3), -5);
});

test("suma con cero", () => {
  assert.equal(add(7, 0), 7);
});
